import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * What the screen is told about a grade's rate; the percent with two decimals, and the date it
     * applies from (null: from the beginning of time) and through (null: no end), and how many
     * versions it has (null in views kept before rates had versions: one). A forward-only rate carries
     * where it was saved in the order claims are added (null: it applies to every claim), and its older
     * versions, newest first, are what a claim added before it was saved falls back to (null in views
     * kept before forward-only rates: none).
     */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to, Integer versions,
            Long forwardAfter, List<OlderView> older) {

        public static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().toPlainString(), rate.getFromDate(),
                    rate.getToDate(), rate.getVersion(), rate.getForwardAfter(),
                    rate.getOlder().stream().map(OlderView::of).toList());
        }
    }

    /** An older version of a rate: its percent with two decimals, to-date, and where it was saved when forward-only. */
    public record OlderView(String pct, LocalDate to, Long forwardAfter) {

        public static OlderView of(RateVersion version) {
            return new OlderView(version.getPct().toPlainString(), version.getToDate(), version.getForwardAfter());
        }
    }

    /**
     * A rate as entered on the form: a percent of 0.00 or more with up to two decimals, and the date
     * it applies from (none: from the beginning of time) and through (none: no end).
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String pct, LocalDate from,
            LocalDate to) {
    }

    /** The rate import box's text: lines of grade,rate,from,to. */
    public record ImportForm(@NotNull @Size(max = 200_000) String text) {
    }

    /** What the screen is told of a rate import: how many rates were set, and the sheet's rates after. */
    public record ImportView(int set, List<RateView> rates) {
    }

    private final RateService service;
    private final RateImportService imports;
    private final SheetHistory history;

    public RateController(RateService service, RateImportService imports, SheetHistory history) {
        this.service = service;
        this.imports = imports;
        this.history = history;
    }

    /**
     * The sheet's rates by grade, each grade's by from-date; a grade with no rate is not listed. With an
     * as-of date, as they stood at the end of it.
     */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.views(sheetId, AsOfGuard.date(asOf)).map(SheetHistory.Views::rates)
                .orElseGet(() -> service.list(sheetId).stream().map(RateView::of).toList());
    }

    /**
     * The rates of the sheet's ancestors, nearest first (its parent's, then its parent's parent's, up to
     * three levels up), each sheet's by grade and from-date: what a grade with no rate in force on the
     * sheet falls back to. With an as-of date, each as it stood at the end of it.
     */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.inherited(sheetId, AsOfGuard.date(asOf)).stream()
                .map(rates -> rates.stream().map(RateView::of).toList()).toList();
    }

    /**
     * Set the rate for a grade from a date (through a to-date, if given), as a new version of any it
     * had from that date; a to-date before the from-date is refused.
     */
    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = GradeService.CODE) String grade,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RateForm form) {
        return RateView.of(service.set(sheetId, SignedIn.name(user), grade, form.from(),
                form.to(), new BigDecimal(form.pct())));
    }

    /**
     * Set a rate per imported line, in order, each as the rate form would; nothing is set when any line
     * is refused.
     */
    @PostMapping("/import")
    public ImportView importRates(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ImportForm form) {
        int set = imports.importRates(sheetId, SignedIn.name(user), form.text()).size();
        return new ImportView(set, service.list(sheetId).stream().map(RateView::of).toList());
    }

    /** What the screen is told of a rate preview: the claims whose due would change, and the sum of the differences. */
    public record PreviewView(int count, String diff) {
    }

    /**
     * How many OPEN and PENDING claims on a grade would show a different due were a candidate rate
     * applied to the grade on every date, and the sum of the differences; nothing is saved.
     */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = GradeService.CODE) String grade,
            @RequestParam @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String pct) {
        RateService.Preview preview = service.preview(sheetId, grade, new BigDecimal(pct));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.grade.GradeService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The rate import box: lines of grade,rate,from,to each set a grade's rate, in order, as the rate form
 * would (replacing any the grade had from the same date); the from- and to-date may be absent or blank.
 * Every line is first held to the rate form's rules; it is one change, so when any line is refused
 * nothing is set and nothing is recorded.
 */
@Service
public class RateImportService {

    /** The most lines one import takes. */
    static final int LINES_MAX = 1000;

    /** A percent as the rate form takes it: 0.00 or more, with up to two decimals. */
    private static final java.util.regex.Pattern PERCENT = java.util.regex.Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    /** A line read from the paste, checked against the form's rules. */
    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private final RateService rates;

    public RateImportService(RateService rates) {
        this.rates = rates;
    }

    /** Set a rate per line of the text, in order; refused as a whole when any line is refused. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                lines.add(line(i + 1, raw[i]));
            }
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of grade,rate,from,to.");
        }
        if (lines.size() > LINES_MAX) {
            throw refused("Paste at most " + LINES_MAX + " lines at once.");
        }
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) {
            set.add(rates.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        }
        return set;
    }

    private static Line line(int number, String text) {
        String[] fields = text.split(",", -1);
        if (fields.length < 2) {
            throw refused("Line " + number + " needs at least a grade and a rate.");
        }
        if (fields.length > 4) {
            throw refused("Line " + number + " has more than grade,rate,from,to.");
        }
        String grade = fields[0].trim();
        if (!grade.matches(GradeService.CODE)) {
            throw refused("Line " + number + ": the grade must be one to three capital letters.");
        }
        String pct = fields[1].trim();
        if (!PERCENT.matcher(pct).matches()) {
            throw refused("Line " + number + ": the rate must be 0.00 or more, with up to two decimals.");
        }
        LocalDate from = date(number, "from", fields.length > 2 ? fields[2] : "");
        LocalDate to = date(number, "to", fields.length > 3 ? fields[3] : "");
        if (from != null && to != null && to.isBefore(from)) {
            throw refused("Line " + number + ": the to-date cannot be before the from-date.");
        }
        return new Line(grade, new BigDecimal(pct), from, to);
    }

    private static LocalDate date(int number, String which, String field) {
        String value = field.trim();
        if (value.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            throw refused("Line " + number + ": the " + which + "-date must be yyyy-mm-dd.");
        }
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * A rate for a grade (A, B or C) on a sheet: a percent with two decimals, applying from its
 * from-date, or from the beginning of time when it has none, through its to-date, or on with no end
 * when it has none. A rate saved with a from-date on or after the sheet's today is forward-only: it
 * applies only to claims added after it was saved (see {@link #seenBy}).
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "version", nullable = false)
    private int version = 1;

    /**
     * Where in the order claims are added the newest version was saved when it is forward-only: it
     * applies only to claims added after; null when it applies to every claim.
     */
    @Column(name = "forward_after")
    private Long forwardAfter;

    /** The rate's older versions, newest first. */
    @OneToMany(fetch = FetchType.EAGER)
    @JoinColumn(name = "rate_id", insertable = false, updatable = false)
    @OrderBy("version DESC")
    private List<RateVersion> older = new ArrayList<>();

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    /** The date the rate applies from; null when it applies from the beginning of time. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** Whether the rate applies to a claim on a date: it has no from-date, or one on or before the date. */
    public boolean appliesOn(LocalDate date) {
        return fromDate == null || !fromDate.isAfter(date);
    }

    /** The last date the rate applies on; null when it has no end. */
    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    /** Whether the rate has ended by a date: it has a to-date before the date. */
    public boolean endedBy(LocalDate date) {
        return toDate != null && toDate.isBefore(date);
    }

    /** The number of the version the rate holds, its newest: 1 for a rate never replaced. */
    public int getVersion() {
        return version;
    }

    /**
     * Replace the rate's value with a new version: the value it held is returned as an older version
     * to keep, and the rate holds the new value as the next version.
     */
    public RateVersion replace(BigDecimal pct, LocalDate toDate, Long forwardAfter) {
        RateVersion replaced = new RateVersion(id, version, this.pct, this.toDate, this.forwardAfter);
        older.add(0, replaced);
        this.pct = pct;
        this.toDate = toDate;
        this.forwardAfter = forwardAfter;
        this.version++;
        return replaced;
    }

    /** Where the newest version was saved in the order claims are added when forward-only; else null. */
    public Long getForwardAfter() {
        return forwardAfter;
    }

    public void setForwardAfter(Long forwardAfter) {
        this.forwardAfter = forwardAfter;
    }

    /** The rate's older versions, newest first. */
    public List<RateVersion> getOlder() {
        return List.copyOf(older);
    }

    /** Hold these older versions (newest first), for a rate held in no store. */
    public void keepOlder(List<RateVersion> versions) {
        older = new ArrayList<>(versions);
    }

    /**
     * The rate as a claim added at a place in the order claims are added sees it (null: a claim not yet
     * stored, added after every rate): its newest version unless that is forward-only and saved after the
     * claim was added, else its newest older version that applies to the claim; empty when none does.
     */
    public Optional<Rate> seenBy(Long added) {
        if (appliesTo(forwardAfter, added)) {
            return Optional.of(this);
        }
        return older.stream().filter(v -> appliesTo(v.getForwardAfter(), added)).findFirst().map(v -> {
            Rate seen = new Rate(sheetId, grade, fromDate, v.getPct());
            seen.setToDate(v.getToDate());
            return seen;
        });
    }

    private static boolean appliesTo(Long forwardAfter, Long added) {
        return forwardAfter == null || added == null || added > forwardAfter;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates by grade, each grade's from the earliest from-date (none first). */
    List<Rate> findBySheetIdOrderByGradeAscFromDateAscIdAsc(String sheetId);

    /** A grade's rates on the sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate with this from-date; a null from-date finds the one with none. */
    Optional<Rate> findBySheetIdAndGradeAndFromDate(String sheetId, String grade, LocalDate fromDate);

    /**
     * The rate a claim on a date uses for a grade: of the grade's rates with no from-date or one on
     * or before the date, the one with the latest; empty when the date is before every rate, or
     * after that one's to-date.
     */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(findBySheetIdAndGrade(sheetId, grade), grade, date);
    }

    /** The rate in force for a grade on a date among these rates (see {@link #findInForce}). */
    static Optional<Rate> inForce(Collection<Rate> rates, String grade, LocalDate date) {
        return inForce(rates.stream(), grade, date);
    }

    /**
     * The rate in force for a grade on a date among these rates as a claim added at a place in the order
     * claims are added sees them (see {@link Rate#seenBy}): a forward-only rate saved after the claim was
     * added is passed over.
     */
    static Optional<Rate> inForceFor(Collection<Rate> rates, String grade, LocalDate date, Long added) {
        return inForce(rates.stream().filter(rate -> rate.getGrade().equals(grade))
                .flatMap(rate -> rate.seenBy(added).stream()), grade, date);
    }

    /** Where the next claim added to any sheet takes its place in the order claims are added. */
    @Query(value = "select next value for claim_added_seq", nativeQuery = true)
    long nextAddedPlace();

    private static Optional<Rate> inForce(Stream<Rate> rates, String grade, LocalDate date) {
        return rates
                .filter(rate -> rate.getGrade().equals(grade))
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> !rate.endedBy(date));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import net.officefloor.hq.app.grade.GradeService;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rates for the grades on a sheet: listed and set. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;
    private final RateVersionRepository versions;

    private final GradeService grades;

    public RateService(RateRepository rates, SheetService sheets, Rollups rollups, Audit audit, PersonRepository people,
            ClaimRepository claims, Dues dues, RateVersionRepository versions, GradeService grades) {
        this.grades = grades;
        this.rates = rates;
        this.versions = versions;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
        this.people = people;
        this.claims = claims;
        this.dues = dues;
    }

    /**
     * What a candidate rate for a grade would change: how many OPEN and PENDING claims of people on
     * the grade (the grade in force on the claim's date) would show a different due, and the sum of
     * the differences (new due minus current due).
     */
    public record Preview(int count, BigDecimal diff) {
    }

    /**
     * Preview a candidate rate applied to a grade on every date, in place of the grade's rates;
     * nothing is saved and nothing is audited. A claim bound by a statement keeps its figure, and a
     * settled claim is not counted.
     */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        grades.requireGrade(sheetId, grade);
        Dues.Basis current = dues.live(sheetId);
        List<Rate> candidate = new ArrayList<>(current.rates().stream()
                .filter(rate -> !rate.getGrade().equals(grade)).toList());
        candidate.add(new Rate(sheetId, grade, null, pct.setScale(2, RoundingMode.UNNECESSARY)));
        Dues.Basis previewed = new Dues.Basis(current.sheet(), candidate, current.inherited(), current.corrected());
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || claim.getSettledDue() != null
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal was = dues.due(claim, grade, current);
            BigDecimal now = dues.due(claim, grade, previewed);
            if (was == null ? now == null : now != null && was.compareTo(now) == 0) {
                continue;
            }
            count++;
            diff = diff.add(orZero(now)).subtract(orZero(was));
        }
        return new Preview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
    }

    private static BigDecimal orZero(BigDecimal value) {
        return value == null ? BigDecimal.ZERO : value;
    }

    /** The sheet's rates by grade. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
    }

    /**
     * Set the rate for a grade from a date (null: from the beginning of time), applying through a
     * to-date (null: no end); a to-date before the from-date is refused. When the grade already has a
     * rate from that same date, its value is kept as an older version and the new one becomes its
     * newest version, the one in force. A rate saved with a from-date on or after the sheet's today is
     * forward-only: it applies only to claims added after it is saved, those already on the sheet keeping
     * the rates that applied to them; one with no from-date, or one before the sheet's today, applies to
     * every claim.
     */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to,
            BigDecimal pct) {
        grades.requireGrade(sheetId, grade);
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        LocalDate today = sheets.load(sheetId).getToday();
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal percent = pct.setScale(2, RoundingMode.UNNECESSARY);
        Long forwardAfter = from != null && !from.isBefore(today) ? rates.nextAddedPlace() : null;
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from).orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, from, percent);
            rate.setToDate(to);
            rate.setForwardAfter(forwardAfter);
        } else {
            versions.save(rate.replace(percent, to, forwardAfter));
        }
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollups.audit(sheetId, user, before);
        return saved;
    }
}
